func streamCountdown(_ n: Int) -> AsyncStream<Int> {      // async unfold
    AsyncStream { cont in
        for v in stride(from: n, through: 1, by: -1) { cont.yield(v) }
        cont.finish()
    }
}

func factorial(_ n: Int) async -> Int {                 // fused async fold
    await streamCountdown(n).reduce(1, *)               // one awaited pass
}
